import convertTextsToString from "../../helpers/strings"

const TwoImage = (data) => {
	let sliders = data.sliders;
	if (!sliders) {
		return <div>Loading </div>;
	}

	if(sliders.error){
		console.log(sliders);
		return <div>Error found check console </div>;
	}
    return (
        <div className="">
			<div className="row g-3 mb-9">
				<div className="col-12 col-xl-6">
					<div className="gift-items-banner w-100 rounded-3 overflow-hidden">
						<div className="bg-holder z-index--1 banner-bg" style={{backgroundImage: "url(" + sliders?.data[1]?.data?.image + ")"}}></div>
						<div className="banner-text text-md-center light">
							<h2 className="text-primary fw-bolder fs-xl-4">{convertTextsToString(sliders?.data[1]?.data?.texts, "title")}</h2>
							<a className="btn btn-lg btn-primary rounded-pill banner-button" href={sliders?.data[1]?.url}>{convertTextsToString(sliders?.data[1]?.data?.texts, "button_text")}</a>
						</div>
					</div>
				</div>
				<div className="col-12 col-xl-6">
					<div className="gift-items-banner w-100 rounded-3 overflow-hidden">
						<div className="bg-holder z-index--1 banner-bg" style={{backgroundImage:  "url(" + sliders?.data[2]?.data?.image + ")"}}></div>
						<div className="banner-text text-md-right light px-2">
							<h2 className="text-white fw-bolder fs-xl-4">{convertTextsToString(sliders?.data[2]?.data?.texts, "title")}</h2>
							<a className="btn btn-lg btn-primary rounded-pill banner-button" href={sliders?.data[2]?.url}>{convertTextsToString(sliders?.data[2]?.data?.texts, "button_text")}</a>
						</div>
					</div>
				</div>
			</div>
		</div>
    );
};
 
 export default TwoImage;