// import Categories from '../components/index/Categories'; 
import ReCAPTCHA from "react-google-recaptcha";
import { api_url, api_token } from '../api/config'
import { useState } from "react";
// import { Form } from 'react-bootstrap';
import axios from "axios";
import { useNavigate } from "react-router-dom";
import FingerprintJS from  "@fingerprintjs/fingerprintjs";
function onChange(value) {
  console.log("Captcha value:", value);
}

const Login = (data) => {
    const fpPromise = FingerprintJS.load()
    const navigate = useNavigate();

    const [formData, setFormData] = useState({
        remember: false
    });
    const [response, setResponse] = useState({});


    let settings = data.settings;
    if(!settings){
        return "Loading";
    }
    settings = settings.data;
    let handleSubmit = (e) => {
        e.preventDefault();
        let visitorId = "";
        fpPromise
        .then(fp => fp.get())
        .then(result => {
            // This is the visitor identifier:
            let requestData = formData;
            requestData.remember = requestData.remember || requestData.remember === "true" ? true : false;
            requestData.fid = result.visitorId
            setResponse({})
            axios.post(api_url + 'api/v1/auth/login', requestData, {
            headers: {
                'C-Token': api_token
            }
            }).then(response => {
                setResponse(response.data);
                localStorage.setItem("auth_token", response.data.token)
                navigate("/");
            }).catch(response => {
                var resp = {};
                resp.error = response.response.data
                setResponse(resp)
            });
        })
    };

    const handleChange = (event) => {
        setFormData({
          ...formData,
          [event.target.name]: event.target.value
        });
      }

      function onChangeCaptcha(value) {
        setFormData({
            ...formData,
            ["captcha"]: value
          });
      }
      
    console.log(settings);
    return (
        <div className="container">
            <div className="row flex-center mt-5 py-5">
                <div className="col-sm-10 col-md-8 col-lg-5 col-xl-5 col-xxl-5">
                    <a className="d-flex flex-center text-decoration-none mb-4" href="/">
                        <div className="d-flex align-items-center fw-bolder fs-5 d-inline-block">
                            <img src="/assets/img/icons/logo.png" alt="phoenix" width="58" />
                        </div>
                    </a>
                    <div className="text-center mb-3">
                        <h3 className="text-1000">Авторизация</h3>
                        <p className="text-700">Войдите в свой аккаунт в 2 шага</p>
                    </div>
                    <form onSubmit={handleSubmit} id="loginForm">
                        {settings.auth.login.phone && settings.auth.login.email ? 
                            <div className="">
                                <ul className="nav nav-underline text-center mx-auto justify-content-center" id="myTab" role="tablist">
                                    <li className="nav-item" key={"101"}>
                                        <a className="nav-link active" id="home-tab" data-bs-toggle="tab" href="#tab-home" role="tab" aria-controls="tab-home" aria-selected="true">
                                            Email
                                        </a>
                                    </li>
                                    <li className="nav-item" key={"102"}>
                                        <a className="nav-link" id="profile-tab" data-bs-toggle="tab" href="#tab-profile" role="tab" aria-controls="tab-profile" aria-selected="false">
                                            Телефон
                                        </a>
                                    </li>
                                </ul>
                                <div className="tab-content mt-1" id="myTabContent">
                                    <div className="tab-pane fade show active" id="tab-home" role="tabpanel" aria-labelledby="home-tab">
                                        <div className="mb-1 text-start">
                                            <label className="form-label" htmlFor="email">Email</label>
                                            <input class={response?.error && response?.error?.error?.email ? "form-control is-invalid" : "form-control"} id="email" name="email" type="text" placeholder="Email" onChange={handleChange} value={formData.email}/>
                                            {!response?.error ? "" : 
                                                !response?.error?.error?.email ? "" :
                                                response.error.error.email.map((element, index) => {
                                                    return (
                                                        <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                                    );
                                                })
                                            }
                                        </div>
                                    </div>
                                    <div className="tab-pane fade" id="tab-profile" role="tabpanel" aria-labelledby="profile-tab">
                                        <div className="mb-1 text-start">
                                            <label className="form-label" htmlFor="phone">Телефон</label>
                                            <input class={response?.error && response?.error?.error?.phone ? "form-control is-invalid" : "form-control"} id="phone" name="phone" type="text" placeholder="+79211234567" onChange={handleChange} value={formData.phone}/>
                                            {!response?.error ? "" : 
                                                !response?.error?.error?.phone ? "" :
                                                response.error.error.phone.map((element, index) => {
                                                    return (
                                                        <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                                    );
                                                })
                                            }
                                        </div>
                                    </div>
                                </div>
                            </div>
                        : (settings.auth.login.email ? 
                                <div className="mb-1 text-start">
                                    <label className="form-label" htmlFor="email">Email</label>
                                    <input class={response?.error && response?.error?.error?.email ? "form-control is-invalid" : "form-control"} id="email" name="email" type="text" placeholder="Email" onChange={handleChange} value={formData.email}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.email ? "" :
                                        response.error.error.email.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                            : 
                                <div className="mb-1 text-start">
                                    <label className="form-label" htmlFor="phone">Телефон</label>
                                    <input class={response?.error && response?.error?.error?.phone ? "form-control is-invalid" : "form-control"} id="phone" name="phone" type="text" placeholder="+79211234567" onChange={handleChange} value={formData.phone}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.phone ? "" :
                                        response.error.error.phone.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                        )}
                        <div className="mb-2 text-start">
                            <label className="form-label" htmlFor="password">Введите пароль</label>
                            <input class={response?.error && response?.error?.error?.password ? "form-control is-invalid" : "form-control"} id="password" name="password" type="password" placeholder="*******" onChange={handleChange} value={formData.password}/>
                            {!response?.error ? "" : 
                                !response?.error?.error?.password ? "" :
                                response.error.error.password.map((element, index) => {
                                    return (
                                        <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                    );
                                })
                            }
                        </div>
                        <div class="row flex-between-center mb-7">
                            {settings.auth.login.remember ?
                                <div class="col-auto">
                                    <div className="form-check mb-3">
                                        <input class={response?.error && response?.error?.error?.remember ? "form-check-input is-invalid" : "form-check-input"} id="remember" name="remember" type="checkbox"  defaultChecked={false} onChange={handleChange}  />
                                        <label className="form-label fs--1 text-none" htmlFor="remember">
                                            Запомнить меня
                                        </label>
                                        {!response?.error ? "" : 
                                            !response?.error?.error?.remember ? "" :
                                            response.error.error.remember.map((element, index) => {
                                                return (
                                                    <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                                );
                                            })
                                        }
                                    </div>
                                </div>
                            :<div class="col-auto"></div>}
                            <div class="col-auto"><a class="fs--1 fw-semi-bold" href="/reset-password">Забыли пароль?</a></div>
                        </div>

                        {settings.auth.login.captcha ? 
                            <div className="mb-3 text-center d-flex justify-content-center">
                                <ReCAPTCHA
                                    sitekey={settings.captcha_site_key}
                                    onChange={onChangeCaptcha}
                                />
                            </div>
                        :""}
                        {!response?.error ? "" : 
                            !response?.error?.error?.captcha ? "" :
                            response.error.error.captcha.map((element, index) => {
                                return (
                                    <div > CAPTCHA ERROR {element}</div>
                                );
                            })
                        }
                        <div className="text-center">
                            <button className="btn btn-primary w-50 mb-3" type="submit">Войти в аккаукнт</button>
                        </div>
                        <div className="text-center">
                            <a className="fs--1 fw-bold" href="/register">
                                Создать аккаунт
                            </a>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
 };
 
 export default Login;