export default function convertTextsToString(data, key, language = "ru") {
    if(!data){
        return "undefined";
    }
    let resp = null;
    data.forEach(element => {
        if(resp){
            return;
        }
        if(element.key && element.key != key){
            return;
        }
        if(element.language != language){
            return;
        }
        resp = element.value;
    });

    if(resp){
        return resp;
    }

    data.forEach(element => {
        if(resp){
            return;
        }
        if(element.key && element.key != key){
            return;
        }

        resp = element.value;
    });

    if(resp){
        return resp;
    }

    return "undefined";
}