import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import Header from './components/layout/Header';
import Footer from './components/layout/Footer';
import ModalEmailConfirm from './components/layout/ModalEmailConfirm';
import ModalPhoneConfirm from './components/layout/ModalPhoneConfirm';
import ModalEmailChange from './components/layout/ModalEmailChange';
import ModalPhoneChange from './components/layout/ModalPhoneChange';
import ModalChangePassword from './components/layout/ModalChangePassword';

import React, {  } from 'react'
import useGetSlider from "./api/slider";
import useGetSettings from "./api/settings";
import useGetCountries from "./api/apis";
import {checkAuth, isAuth} from "./api/auth";

import Home from './pages/Home';
import Login from './pages/Login';
import Register from './pages/Register';
import Bonuses from './pages/Bonuses';
import Logout from './pages/Logout';
import ResetPassword from './pages/ResetPassword';
import SetPassword from './pages/SetPassword';

import ScrollToTop from './utils/Scroll-top';
import Profile from './pages/Profile';
import useGetMe from './api/getMe';
import useWindowDimensions from './helpers/height';

function App() {
   const { height, width } = useWindowDimensions();
   let sliders = useGetSlider();
   let settings = useGetSettings();
   let userData = useGetMe();
   checkAuth();
   let countries = useGetCountries();
   let is_auth = isAuth();
   document.querySelector("footer")?.classList.remove("fixed-bottom")
   document.querySelector("footer")?.classList.add("position-relative")
   var head= document.getElementsByTagName('head')[0];
   var script= document.createElement('script');
   script.src= '/assets/js/esplatform.js';
   head.appendChild(script);

   // if(document.querySelector("footer")?.clientHeight)
   setInterval(() => {
      if(document.getElementById("app")?.clientHeight){
         if(document.getElementById("app")?.clientHeight + 150 > height){
            document.querySelector("footer")?.classList.remove("fixed-bottom")
            document.querySelector("footer")?.classList.add("position-relative")
         }else{
            document.querySelector("footer")?.classList.add("fixed-bottom")
            document.querySelector("footer")?.classList.remove("position-relative")
         }
      }
   }, 100);
   
   // if(document.getElementById('container').clientHeight)
   return (
      <div className="app">
         <Router>
            <ScrollToTop />
            <main className="main">
               <Header is_auth={is_auth} settings={settings}/>
               <Routes>
                  <Route path="/" element={<Home sliders={sliders}/>} />
                  <Route path="/bonuses" element={<Bonuses/>} />


                  <Route path="/login" element={<Login settings={settings}/>} />
                  <Route path="/register" element={<Register settings={settings} countries={countries}/>} />
                  <Route path="/reset-password" element={<ResetPassword settings={settings}/>} />
                  <Route path="/set-password" element={<SetPassword settings={settings}/>} />
                  <Route path="/logout" element={<Logout/>} />

                  <Route path="/profile/settings" element={<Profile settings={settings} pageName={"settings"} userData={userData} countries={countries}/>} />




                  <Route path="/bonuses" element={<Bonuses settings={settings} countries={countries}/>} />
               </Routes>
               <Footer />
            </main>
            {is_auth ? 
               <div>
                  <ModalEmailConfirm />
                  <ModalPhoneConfirm />
                  <ModalEmailChange />
                  <ModalPhoneChange />
                  <ModalChangePassword />
               </div>
            : ""}
         </Router>
      </div>
   );
}

export default App;
