// import Categories from '../components/index/Categories'; 
import ReCAPTCHA from "react-google-recaptcha";
import { api_url, api_token } from '../api/config'
import { useState } from "react";
// import { Form } from 'react-bootstrap';
import axios from "axios";
import { useNavigate } from "react-router-dom";
import FingerprintJS from  "@fingerprintjs/fingerprintjs";

function onChange(value) {
  console.log("Captcha value:", value);
}

const ResetPasswword = (data) => {
    const fpPromise = FingerprintJS.load()

    const navigate = useNavigate();

    const [formData, setFormData] = useState({
        remember: false
    });
    const [response, setResponse] = useState({});


    let settings = data.settings;
    if(!settings){
        return "Loading";
    }
    settings = settings.data;
    // document.querySelector("footer")?.classList.add("fixed-bottom")
    // document.querySelector("footer")?.classList.remove("position-relative")
    let handleSubmit = (e) => {
        e.preventDefault();
        let visitorId = "";
        fpPromise
        .then(fp => fp.get())
        .then(result => {
            // This is the visitor identifier:
            let requestData = formData;
            requestData.fid = result.visitorId
            setResponse({})
            axios.post(api_url + 'api/v1/auth/reset-password', requestData, {
            headers: {
                'C-Token': api_token
            }
            }).then(response => {
                setResponse(response.data);
                localStorage.setItem("resethash", response.data.hash)
                navigate("/set-password");
            }).catch(response => {
                var resp = {};
                resp.error = response.response.data
                setResponse(resp)
            });
        })
    };

    const handleChange = (event) => {
        setFormData({
            ...formData,
            [event.target.name]: event.target.value
        });
    }

    function onChangeCaptcha(value) {
        setFormData({
            ...formData,
            ["captcha"]: value
        });
    }
    return (
        <div className="container">
            <div className="row flex-center mt-5 py-5">
                <div className="col-sm-10 col-md-8 col-lg-5 col-xl-5 col-xxl-5">
                    <a className="d-flex flex-center text-decoration-none mb-4" href="/">
                        <div className="d-flex align-items-center fw-bolder fs-5 d-inline-block">
                            <img src="/assets/img/icons/logo.png" alt="phoenix" width="58" />
                        </div>
                    </a>
                    <div className="text-center mb-3">
                        <h3 className="text-1000">Забыли пароль?</h3>
                        <p className="text-700">В 0 шаг всего лишь восстановите!</p>
                    </div>
                    <form onSubmit={handleSubmit} id="resetForm">
                        {settings.auth.reset.phone && settings.auth.reset.email ? 
                            <div className="">
                                <ul className="nav nav-underline text-center mx-auto justify-content-center" id="myTab" role="tablist">
                                    <li className="nav-item" key={"101"}>
                                        <a className="nav-link active" id="home-tab" data-bs-toggle="tab" href="#tab-home" role="tab" aria-controls="tab-home" aria-selected="true">
                                            Email
                                        </a>
                                    </li>
                                    <li className="nav-item" key={"102"}>
                                        <a className="nav-link" id="profile-tab" data-bs-toggle="tab" href="#tab-profile" role="tab" aria-controls="tab-profile" aria-selected="false">
                                            Телефон
                                        </a>
                                    </li>
                                </ul>
                                <div className="tab-content mt-3" id="myTabContent">
                                    <div className="tab-pane fade show active" id="tab-home" role="tabpanel" aria-labelledby="home-tab">
                                        <div class="d-flex align-items-center mb-5">
                                            <input class={response?.error && response?.error?.error?.email ? "form-control flex-1 is-invalid" : "form-control flex-1"} id="email" name="email" type="email" placeholder="Email" onChange={handleChange} value={formData.email}/>
                                            <button class="btn btn-primary ms-2" type="submit">
                                                Восстановить
                                                <span class="fas fa-chevron-right ms-2"></span>
                                            </button>
                                            {!response?.error ? "" : 
                                                !response?.error?.error?.email ? "" :
                                                response.error.error.email.map((element, index) => {
                                                    return (
                                                        <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                                    );
                                                })
                                            }
                                        </div>
                                    </div>
                                    <div className="tab-pane fade" id="tab-profile" role="tabpanel" aria-labelledby="profile-tab">
                                        <div class="d-flex align-items-center mb-5">
                                            <input class={response?.error && response?.error?.error?.phone ? "form-control flex-1 is-invalid" : "form-control flex-1"} id="phone" name="phone" type="phone" placeholder="phone" onChange={handleChange} value={formData.phone}/>
                                            <button class="btn btn-primary ms-2" type="submit">
                                                Восстановить
                                                <span class="fas fa-chevron-right ms-2"></span>
                                            </button>
                                            {!response?.error ? "" : 
                                                !response?.error?.error?.phone ? "" :
                                                response.error.error.phone.map((element, index) => {
                                                    return (
                                                        <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                                    );
                                                })
                                            }
                                        </div>
                                    </div>
                                </div>
                            </div>
                        : (settings.auth.reset.email ? 
                                <div class="d-flex align-items-center mb-5">
                                    <input class={response?.error && response?.error?.error?.email ? "form-control flex-1 is-invalid" : "form-control flex-1"} id="email" name="email" type="email" placeholder="Email" onChange={handleChange} value={formData.email}/>
                                    <button class="btn btn-primary ms-2" type="submit">
                                        Восстановить
                                        <span class="fas fa-chevron-right ms-2"></span>
                                    </button>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.email ? "" :
                                        response.error.error.email.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                            : 
                                <div class="d-flex align-items-center mb-5">
                                    <input class={response?.error && response?.error?.error?.phone ? "form-control flex-1 is-invalid" : "form-control flex-1"} id="phone" name="phone"  type="phone" placeholder="phone" onChange={handleChange} value={formData.phone}/>
                                    <button class="btn btn-primary ms-2" type="submit">
                                        Восстановить
                                        <span class="fas fa-chevron-right ms-2"></span>
                                    </button>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.phone ? "" :
                                        response.error.error.phone.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                        )}

                        {settings.auth.login.captcha ? 
                            <div className="mb-3 text-center d-flex justify-content-center">
                                <ReCAPTCHA
                                    sitekey={settings.captcha_site_key}
                                    onChange={onChangeCaptcha}
                                />
                            </div>
                        :""}
                        {!response?.error ? "" : 
                            !response?.error?.error?.captcha ? "" :
                            response.error.error.captcha.map((element, index) => {
                                return (
                                    <div > CAPTCHA ERROR {element}</div>
                                );
                            })
                        }
                        <div className="text-center">
                            <a class="fs--1 fw-bold" href="/login">Вспомнили аккаунт?</a>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
 };
 
 export default ResetPasswword;