import { api_url, api_token } from '../../api/config'
import { useState } from "react";
import axios from "axios";
import FingerprintJS from  "@fingerprintjs/fingerprintjs";
const Settings = (data) => {
    let userData = data.userData;
    const dob = userData?.data?.dob
    const dateTime = new Date(dob * 1000).toISOString().slice(0,16)
    const [formData, setFormData] = useState({
        email: userData.email,
        phone: userData.phone,
        username: userData.username,
        first_name: userData.data.first_name,
        second_name: userData.data.second_name,
        last_name: userData.data.last_name,
        gender: userData.data.gender,
        dob: dateTime,
        country: userData.data.country,
        city: userData.data.city,
        address: userData.data.address,
        zip: userData.data.zip,
    });
    let countries = data.countries;
    countries = countries.data;


    const fpPromise = FingerprintJS.load()
    const [response, setResponse] = useState({});
    const handleChange = (event) => {
        setFormData({
          ...formData,
          [event.target.name]: event.target.value
        });
    }

    if(userData){
        if(!userData?.data?.email_verified_at || userData?.data?.email_verified_at == 0){
            if(response?.error?.error?.email && response?.error?.error?.email.length == 0){
                response.error.error.email.push("Не подтверждена почта");
            }else{
                if(!response?.error)
                    response.error = {};
                if(!response?.error?.error)
                    response.error.error = {};
                if(!response?.error?.error?.email)
                    response.error.error.email = [];
                if(response?.error?.error?.email.length == 0)
                    response.error.error.email.push("Не подтверждена почта");
            }
        }

        if(!userData?.data?.phone_verified_at || userData?.data?.phone_verified_at == 0){
            if(response?.error?.error?.phone && response?.error?.error?.phone.length == 0){
                response.error.error.phone.push("Не подтвержден номер телефона");
            }else{
                if(!response?.error)
                    response.error = {};
                if(!response?.error?.error)
                    response.error.error = {};
                if(!response?.error?.error?.phone)
                    response.error.error.phone = [];
                if(response?.error?.error?.phone.length == 0)
                    response.error.error.phone.push("Не подтвержден номер телефона");
            }
        }
    }

    let handleSubmit = (e) => {
        e.preventDefault();
        let visitorId = "";
        fpPromise
        .then(fp => fp.get())
        .then(result => {
            // This is the visitor identifier:
            let requestData = formData;
            requestData.promo = requestData.promo || requestData.promo === "true" ? true : false;
            requestData.fid = result.visitorId
            if(requestData.dob && requestData.dob < 10000){
                requestData.dob = 0
            }
            if(typeof requestData.dob == "string"){
                const date = +new Date(requestData.dob)
                requestData.dob = parseInt(parseInt(date) / 1000)
            }
            setResponse({})
            axios.post(api_url + 'api/v1/private/set/my/data', requestData, {
            headers: {
                'C-Token': api_token,
                'Authorization': `Bearer: ${localStorage.getItem("auth_token")}`
            }
            }).then(response => {
                if(response.data.hasErrors){
                    var resp = {};
                    resp.error = response.data;
                    setResponse(resp);
                }

                if(response.data.email_change_hash && response.data.email_change_hash.length > 0){
                    localStorage.setItem("change_email_token", response.data.email_change_hash)
                    document.getElementById("openModalEmailChangeBtn").click()
                    setResponse(response);
                    return;
                }

                if(response.data.phone_change_hash && response.data.phone_change_hash.length > 0){
                    localStorage.setItem("change_phone_token", response.data.phone_change_hash)
                    document.getElementById("openModalPhoneChangeBtn").click()
                    setResponse(response);
                    return;
                }
            }).catch(response => {
                var resp = {};
                resp.error = response.response.data
                setResponse(resp)
            });
        })
    };
    return (
		<form onSubmit={handleSubmit} id="profileDataForm"  class="row g-3 mb-5">
            <div class="col-12 col-lg-6">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="email">
                    Email 

                    {userData.email.length == 0 || userData?.data?.email_verified_at > 0 ? "" : 
                        <button class="btn btn-outline-success btn-sm fs--2 mx-2" type="button" data-bs-toggle="modal" data-bs-target="#emailConfirmModal" aria-haspopup="true" aria-expanded="false" data-bs-reference="parent">Верифицировать</button>
                    }
                </label>
                
                <input class={userData.email.length > 0 &&  (response?.error && response?.error?.error?.email) ? "form-control is-invalid" : "form-control"} id="email" name="email" type="text" placeholder="Email" onChange={handleChange} value={formData.email}/>
                {!response?.error ? "" : 
                    userData.email.length == 0 || !response?.error?.error?.email ? "" :
                    response.error.error.email.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            <div class="col-12 col-lg-6">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="email">
                    Телефон 
                    {userData.phone.length == 0 || userData?.data?.phone_verified_at > 0 ? "" : 
                        <button class="btn btn-outline-success btn-sm fs--2 mx-2" type="button" data-bs-toggle="modal" data-bs-target="#phoneConfirmModal" aria-haspopup="true" aria-expanded="false" data-bs-reference="parent">Верифицировать</button>
                    }
                </label>
                
                <input class={userData.phone.length > 0 &&  (response?.error && response?.error?.error?.phone) ? "form-control is-invalid" : "form-control"} id="phone" name="phone" type="text" placeholder="+79211234567" onChange={handleChange} value={formData.phone}/>
                {!response?.error ? "" : 
                    userData.phone.length == 0 || !response?.error?.error?.phone ? "" :
                    response.error.error.phone.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            <div class="col-12">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="email">
                    Username
                </label>
                
                <input class={response?.error && response?.error?.error?.username ? "form-control is-invalid" : "form-control"} id="username" name="username" type="text" placeholder="pro100kill3r228" onChange={handleChange} value={formData.username}/>
                {!response?.error ? "" : 
                    !response?.error?.error?.username ? "" :
                    response.error.error.username.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            <div class="col-12 col-lg-4">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="email">
                    Ваша фамилия
                </label>
                
                <input class={response?.error && response?.error?.error?.last_name ? "form-control is-invalid" : "form-control"} id="last_name" name="last_name" type="text" placeholder="Силин" onChange={handleChange} value={formData.last_name}/>
                {!response?.error ? "" : 
                    !response?.error?.error?.last_name ? "" :
                    response.error.error.last_name.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            <div class="col-12 col-lg-4">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="email">
                    Ваше имя
                </label>
                
                <input class={response?.error && response?.error?.error?.first_name ? "form-control is-invalid" : "form-control"} id="first_name" name="first_name" type="text" placeholder="Святослав" onChange={handleChange} value={formData.first_name}/>
                {!response?.error ? "" : 
                    !response?.error?.error?.first_name ? "" :
                    response.error.error.first_name.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            <div class="col-12 col-lg-4">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="email">
                    Ваше отчество
                </label>
                
                <input class={response?.error && response?.error?.error?.second_name ? "form-control is-invalid" : "form-control"} id="second_name" name="second_name" type="text" placeholder="Юлианович" onChange={handleChange} value={formData.second_name}/>
                {!response?.error ? "" : 
                    !response?.error?.error?.second_name ? "" :
                    response.error.error.second_name.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            
            <div class="col-12 col-lg-6">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="gender">Выберите пол</label>
                <select class={response?.error && response?.error?.error?.gender ? "form-select is-invalid" : "form-select"} name="gender" id="gender"  onChange={handleChange} value={formData.gender}>
                    <option disabled>Не выбрано</option>
                    <option value="male">Мужчина</option>
                    <option value="female">Женщина</option>
                    <option disabled value="other">Не определились?</option>
                </select>
                {!response?.error ? "" : 
                    !response?.error?.error?.gender ? "" :
                    response.error.error.gender.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>
            <div class="col-12 col-lg-6">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="dob">Дата рождения</label>
                <input class={response?.error && response?.error?.error?.dob ? "form-control is-invalid" : "form-control"} id="dob" name="dob" type="datetime-local" placeholder=""  onChange={handleChange} value={formData.dob}/>
                {!response?.error ? "" : 
                    !response?.error?.error?.dob ? "" :
                    response.error.error.dob.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            <div class="col-12 col-lg-3">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="email">
                    Ваша страна
                </label>
                <select class={response?.error && response?.error?.error?.country ? "form-select is-invalid" : "form-select"}  name="country" id="country"  onChange={handleChange} value={formData.country}>
                    {countries.map((element, index) => {
                        return (
                            <option onChange={handleChange} value={element}>{element}</option>
                        );
                    })}
                </select>
                {!response?.error ? "" : 
                    !response?.error?.error?.country ? "" :
                    response.error.error.country.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            <div class="col-12 col-lg-3">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="email">
                    Ваш город
                </label>
                <input class={response?.error && response?.error?.error?.city ? "form-control is-invalid" : "form-control"} id="city" name="city" type="text" placeholder="Санкт Петербург"  onChange={handleChange} value={formData.city}/>
                {!response?.error ? "" : 
                    !response?.error?.error?.city ? "" :
                    response.error.error.city.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            <div class="col-12 col-lg-3">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="email">
                    Ваш адрес
                </label>
                <input class={response?.error && response?.error?.error?.address ? "form-control is-invalid" : "form-control"} id="address" name="address" type="text" placeholder="улица Пушкина дом колотушкина"  onChange={handleChange} value={formData.address}/>
                {!response?.error ? "" : 
                    !response?.error?.error?.address ? "" :
                    response.error.error.address.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            <div class="col-12 col-lg-3">
                <label className="form-label text-1000 fs-0 ps-0 text-capitalize lh-sm mb-2" htmlFor="email">
                    Ваш почтовый индекс
                </label>
                <input class={response?.error && response?.error?.error?.zip ? "form-control is-invalid" : "form-control"} id="zip" name="zip" type="text" placeholder="228"  onChange={handleChange} value={formData.zip}/>
                {!response?.error ? "" : 
                    !response?.error?.error?.zip ? "" :
                    response.error.error.zip.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            <div class="col-12 text-end">
                <input class={response?.error && response?.error?.error?.promo ? "form-check-input is-invalid" : "form-check-input"} id="promo" name="promo" type="checkbox"  defaultChecked={true} onChange={handleChange}  />
                <label className="form-label fs--1 text-none text-secondary" htmlFor="email">
                    Я разрешаю присылать мне рекламные кампании
                </label>
                {!response?.error ? "" : 
                    !response?.error?.error?.promo ? "" :
                    response.error.error.promo.map((element, index) => {
                        return (
                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                        );
                    })
                }
            </div>

            <div class="text-end">
                <button class="btn btn-primary px-7" type="submit">Сохранить изменения</button>
            </div>
        </form>
		
    );
};
 
 export default Settings;