import { api_url, api_token } from '../../api/config'
import { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import FingerprintJS from  "@fingerprintjs/fingerprintjs";


function ModalChangePassword(data) {
    const navigate = useNavigate();
    let hash = data.hash;
    const [formData, setFormData] = useState({});
    const fpPromise = FingerprintJS.load()
    const [response, setResponse] = useState({});
    const handleChange = (event) => {
        setFormData({
          ...formData,
          [event.target.name]: event.target.value
        });
    }

    let handleSubmit = (e) => {
        e.preventDefault();
        let url = api_url + 'api/v1/auth/change/user/password';
        if(localStorage.getItem("auth_change_password_token")){
            url = api_url + 'api/v1/auth/change/user/2fa-password';
            setResponse({error: {error: {code: ["Вы не отправили смс, нажмите кнопку чтобы отправить смс"]}}});
            return;
        }
        let visitorId = "";
        fpPromise
        .then(fp => fp.get())
        .then(result => {
            formData.fid = result.visitorId;
            if(localStorage.getItem("auth_change_password_token"))
                formData.hash = localStorage.getItem("auth_change_password_token");
            
            setResponse({})
            axios.post(url, formData, {
                headers: {
                    'C-Token': api_token,
                    'Authorization': `Bearer: ${localStorage.getItem("auth_token")}`
                }
            }).then(response => {
                setResponse(response.data);
                if(response.data.hash.length > 0){
                    localStorage.setItem("auth_change_password_token", response.data.hash)
                }else{
                    localStorage.removeItem("auth_change_password_token")
                }
                // localStorage.removeItem("verification_phone_token")
            }).catch(response => {
                var resp = {};
                resp.error = response.response.data
                setResponse(resp)
            });
        })
    };

    return (
        <div class="modal fade" id="changePasswordModal" data-bs-keyboard="false" tabindex="-1" aria-labelledby="changePasswordModal" aria-hidden="true">
            <div class="modal-dialog modal-md modal-dialog-centered">
                <div class="modal-content bg-100 p-6">
                <div class="modal-header border-0 p-0 mb-2">
                    <h3 class="mb-0"></h3>
                    <button class="btn btn-sm btn-esplatform-secondary" data-bs-dismiss="modal" aria-label="Close"><span class="fas fa-times text-danger"></span></button>
                </div>
                <div class="modal-body px-0">
                    
                    
                <div className="row flex-center pb-5">
                    <div className="col-sm-10 col-md-8 col-lg-5 col-xl-6 col-xxl-7">
                        <a className="d-flex flex-center text-decoration-none mb-7" href="/">
                            <div className="d-flex align-items-center fw-bolder fs-5 d-inline-block">
                                <img src="/assets/img/icons/logo.png" alt="escasino" width="58" />
                            </div>
                        </a>
                        <div className="text-center mb-3">
                            <h3 className="text-1000">Смена пароля</h3>
                        </div>
                        <form onSubmit={handleSubmit} id="modalchangePasswordForm">
                            {localStorage.getItem("auth_change_password_token") ?
                                <div className="mb-3 text-start">
                                    <label className="form-label" htmlFor="code">Код подтверждения 2fa</label>
                                    <input class={response?.error && response?.error?.error?.code ? "form-control is-invalid" : "form-control"} id="code" name="code" type="code" placeholder="17235126" onChange={handleChange} value={formData.code}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.code ? "" :
                                        response.error.error.code.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                            : "" }
                            <div className="mb-3 text-start">
                                <label className="form-label" htmlFor="old_password">Старый пароль</label>
                                <input class={response?.error && response?.error?.error?.old_password ? "form-control is-invalid" : "form-control"} id="old_password" name="old_password" type="password" placeholder="*******" onChange={handleChange} value={formData.old_password}/>
                                {!response?.error ? "" : 
                                    !response?.error?.error?.old_password ? "" :
                                    response.error.error.old_password.map((element, index) => {
                                        return (
                                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                        );
                                    })
                                }
                            </div>
                            <div className="row g-3 mb-4">
                                <div className="col-lg-6">
                                    <label className="form-label" htmlFor="password">Новый пароль</label>
                                    <input class={response?.error && response?.error?.error?.password ? "form-control is-invalid" : "form-control"} id="password" name="password" type="password" placeholder="*******" onChange={handleChange} value={formData.password}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.password ? "" :
                                        response.error.error.password.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                                <div className="col-lg-6">
                                    <label className="form-label" htmlFor="repeat_password">Повторите пароль</label>
                                    <input class={response?.error && response?.error?.error?.repeat_password ? "form-control is-invalid" : "form-control"} id="repeat_password" name="repeat_password" type="password" placeholder="*******" onChange={handleChange} value={formData.repeat_password}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.repeat_password ? "" :
                                        response.error.error.repeat_password.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                            </div>
                            <div className="text-center">
                                <button className="btn btn-primary mb-3 w-50" type="submit">Подтвердить</button>
                            </div>
                        </form>
                    </div>
                </div>



                </div>
                </div>
            </div>
        </div>
    );
 }
 
 export default ModalChangePassword;
 