import Categories from '../components/index/Categories'; 
import ReCAPTCHA from "react-google-recaptcha";
import { api_url, api_token } from '../api/config'
import { useState } from "react";
import { Form } from 'react-bootstrap';
import axios from "axios";
import { useNavigate } from "react-router-dom";
import FingerprintJS from  "@fingerprintjs/fingerprintjs";

function onChange(value) {
  console.log("Captcha value:", value);
}

const Register = (data) => {
    const fpPromise = FingerprintJS.load()

    const navigate = useNavigate();

    const [formData, setFormData] = useState({
        promo: true
    });
    const [response, setResponse] = useState({});


    let settings = data.settings;
    if(!settings){
        return "Loading";
    }
    settings = settings.data;
    let countries = data.countries;
    if(!countries){
        return "Loading";
    }
    countries = countries.data;

    let handleSubmit = (e) => {
        e.preventDefault();
        let visitorId = "";
        fpPromise
        .then(fp => fp.get())
        .then(result => {
            // This is the visitor identifier:
            let requestData = formData;
            requestData.promo = requestData.promo || requestData.promo === "true" ? true : false;
            requestData.terms = requestData.terms || requestData.terms === "true" ? true : false;
            requestData.fid = result.visitorId
            if(requestData.dob && requestData.dob < 10000){
                requestData.dob = 0
            }
            if(typeof requestData.dob == "string"){
                const date = +new Date(requestData.dob)
                requestData.dob = parseInt(parseInt(date) / 1000)
            }
            setResponse({})
            axios.post(api_url + 'api/v1/auth/register', requestData, {
            headers: {
                'C-Token': api_token
            }
            }).then(response => {
                setResponse(response.data);
                localStorage.setItem("auth_token", response.data.token)
                navigate("/");
            }).catch(response => {
                var resp = {};
                resp.error = response.response.data
                setResponse(resp)
            });
        })
    };

    const handleChange = (event) => {
        setFormData({
          ...formData,
          [event.target.name]: event.target.value
        });
    }

      function onChangeCaptcha(value) {
        setFormData({
            ...formData,
            ["captcha"]: value
          });
      }
    
    return (
        <div className="container">
            <div className="row flex-center mt-5 py-5">
                <div className="col-sm-10 col-md-8 col-lg-5 col-xl-5 col-xxl-5">
                    <a className="d-flex flex-center text-decoration-none mb-4" href="/">
                        <div className="d-flex align-items-center fw-bolder fs-5 d-inline-block">
                            <img src="/assets/img/icons/logo.png" alt="phoenix" width="58" />
                        </div>
                    </a>
                    <div className="text-center mb-3">
                        <h3 className="text-1000">Регистрация</h3>
                        <p className="text-700">Создайте свой аккаунт в 3 шага</p>
                    </div>
                    <form onSubmit={handleSubmit} id="registerForm">
                        {settings.auth.register.phone && settings.auth.register.email ? 
                            <div className="">
                                <ul className="nav nav-underline text-center mx-auto justify-content-center" id="myTab" role="tablist">
                                    <li className="nav-item" key={"101"}>
                                        <a className="nav-link active" id="home-tab" data-bs-toggle="tab" href="#tab-home" role="tab" aria-controls="tab-home" aria-selected="true">
                                            Email
                                        </a>
                                    </li>
                                    <li className="nav-item" key={"102"}>
                                        <a className="nav-link" id="profile-tab" data-bs-toggle="tab" href="#tab-profile" role="tab" aria-controls="tab-profile" aria-selected="false">
                                            Телефон
                                        </a>
                                    </li>
                                </ul>
                                <div className="tab-content mt-1" id="myTabContent">
                                    <div className="tab-pane fade show active" id="tab-home" role="tabpanel" aria-labelledby="home-tab">
                                        <div className="mb-1 text-start">
                                            <label className="form-label" htmlFor="email">Email</label>
                                            <input class={response?.error && response?.error?.error?.email ? "form-control is-invalid" : "form-control"} id="email" name="email" type="text" placeholder="Email" onChange={handleChange} value={formData.email}/>
                                            {!response?.error ? "" : 
                                                !response?.error?.error?.email ? "" :
                                                response.error.error.email.map((element, index) => {
                                                    return (
                                                        <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                                    );
                                                })
                                            }
                                        </div>
                                    </div>
                                    <div className="tab-pane fade" id="tab-profile" role="tabpanel" aria-labelledby="profile-tab">
                                        <div className="mb-1 text-start">
                                            <label className="form-label" htmlFor="phone">Телефон</label>
                                            <input class={response?.error && response?.error?.error?.phone ? "form-control is-invalid" : "form-control"} id="phone" name="phone" type="text" placeholder="+79211234567" onChange={handleChange} value={formData.phone}/>
                                            {!response?.error ? "" : 
                                                !response?.error?.error?.phone ? "" :
                                                response.error.error.phone.map((element, index) => {
                                                    return (
                                                        <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                                    );
                                                })
                                            }
                                        </div>
                                    </div>
                                </div>
                            </div>
                        : (settings.auth.register.email ? 
                                <div className="mb-1 text-start">
                                    <label className="form-label" htmlFor="email">Email</label>
                                    <input class={response?.error && response?.error?.error?.email ? "form-control is-invalid" : "form-control"} id="email" name="email" type="text" placeholder="Email" onChange={handleChange} value={formData.email}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.email ? "" :
                                        response.error.error.email.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                            : 
                                <div className="mb-1 text-start">
                                    <label className="form-label" htmlFor="phone">Телефон</label>
                                    <input class={response?.error && response?.error?.error?.phone ? "form-control is-invalid" : "form-control"} id="phone" name="phone" type="text" placeholder="+79211234567" onChange={handleChange} value={formData.phone}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.phone ? "" :
                                        response.error.error.phone.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                        )}
                        <div className="row g-3 mb-1">
                            <div className="col-sm-6">
                                    <label className="form-label" htmlFor="password">Введите пароль</label>
                                    <input class={response?.error && response?.error?.error?.password ? "form-control is-invalid" : "form-control"} id="password" name="password" type="password" placeholder="*******" onChange={handleChange} value={formData.password}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.password ? "" :
                                        response.error.error.password.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                            <div className="col-sm-6">
                                <label className="form-label" htmlFor="repeat_password">Повторите пароль</label>
                                <input class={response?.error && response?.error?.error?.repeat_password ? "form-control is-invalid" : "form-control"} id="repeat_password" name="repeat_password" type="password" placeholder="*******" onChange={handleChange} value={formData.repeat_password}/>
                                {!response?.error ? "" : 
                                    !response?.error?.error?.repeat_password ? "" :
                                    response.error.error.repeat_password.map((element, index) => {
                                        return (
                                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                        );
                                    })
                                }
                            </div>
                        </div>
                        <div className="mb-1 text-start">
                            <label className="form-label" htmlFor="currency">Выберите валюту</label>
                            <select class={response?.error && response?.error?.error?.currency ? "form-select is-invalid" : "form-select"} name="currency" id="currency"  onChange={handleChange} value={formData.currency}>
                                <option disabled selected>Не выбрано</option>
                                {settings.currencies.map((element, index) => {
                                    return (
                                        <option onChange={handleChange} value={element}>{element}</option>
                                    );
                                })}
                            </select>
                            {!response?.error ? "" : 
                                !response?.error?.error?.currency ? "" :
                                response.error.error.currency.map((element, index) => {
                                    return (
                                        <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                    );
                                })
                            }
                        </div>
                        {settings.auth.register.username ? 
                            <div className="mb-1 text-start">
                                <label className="form-label" htmlFor="username">Username</label>
                                <input class={response?.error && response?.error?.error?.username ? "form-control is-invalid" : "form-control"} id="username" name="username" type="text" placeholder="vioriel"  onChange={handleChange} value={formData.username}/>
                                {!response?.error ? "" : 
                                    !response?.error?.error?.username ? "" :
                                    response.error.error.username.map((element, index) => {
                                        return (
                                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                        );
                                    })
                                }
                            </div>
                        :""}
                        {settings.auth.register.full_name ? 
                           <div className="row g-3 mb-1">
                                <div className="col-md-4">
                                    <label className="form-label" htmlFor="last_name">Ваша фамилия</label>
                                    <input class={response?.error && response?.error?.error?.last_name ? "form-control is-invalid" : "form-control"} id="last_name" name="last_name" type="text" placeholder="Силин"  onChange={handleChange} value={formData.last_name}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.last_name ? "" :
                                        response.error.error.last_name.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                                <div className="col-md-4 col-sm-6">
                                    <label className="form-label" htmlFor="first_name">Ваше имя</label>
                                        <input class={response?.error && response?.error?.error?.first_name ? "form-control is-invalid" : "form-control"} id="first_name" name="first_name" type="text" placeholder="Святослав"  onChange={handleChange} value={formData.first_name}/>
                                        {!response?.error ? "" : 
                                            !response?.error?.error?.first_name ? "" :
                                            response.error.error.first_name.map((element, index) => {
                                                return (
                                                    <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                                );
                                            })
                                        }
                                    </div>
                                <div className="col-md-4 col-sm-6">
                                    <label className="form-label" htmlFor="second_name">Ваше отчество</label>
                                    <input class={response?.error && response?.error?.error?.second_name ? "form-control is-invalid" : "form-control"} id="second_name" name="second_name" type="text" placeholder="Юлианович"  onChange={handleChange} value={formData.second_name}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.second_name ? "" :
                                        response.error.error.second_name.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                            </div>
                        :""}
                        {settings.auth.register.dob ? 
                            <div className="mb-1 text-start">
                                <label className="form-label" htmlFor="dob">Дата рождения</label>
                                <input class={response?.error && response?.error?.error?.dob ? "form-control is-invalid" : "form-control"} id="dob" name="dob" type="datetime-local" placeholder=""  onChange={handleChange} value={formData.dob}/>
                                {!response?.error ? "" : 
                                    !response?.error?.error?.dob ? "" :
                                    response.error.error.dob.map((element, index) => {
                                        return (
                                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                        );
                                    })
                                }
                            </div>
                        :""}
                        {settings.auth.register.gender ? 
                            <div className="mb-1 text-start">
                                <label className="form-label" htmlFor="gender">Выберите пол</label>
                                <select class={response?.error && response?.error?.error?.gender ? "form-select is-invalid" : "form-select"} name="gender" id="gender"  onChange={handleChange} value={formData.gender}>
                                    <option disabled selected>Не выбрано</option>
                                    <option value="male">Мужчина</option>
                                    <option value="female">Женщина</option>
                                    <option disabled value="other">Не определились?</option>
                                </select>
                                {!response?.error ? "" : 
                                    !response?.error?.error?.gender ? "" :
                                    response.error.error.gender.map((element, index) => {
                                        return (
                                            <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                        );
                                    })
                                }
                            </div>
                        :""}
                        {settings.auth.register.city ? 
                           <div className="row g-3 mb-1">
                                <div className="col-sm-6">
                                    <label className="form-label" htmlFor="country">Ваша страна</label>
                                    <select class={response?.error && response?.error?.error?.country ? "form-select is-invalid" : "form-select"}  name="country" id="country"  onChange={handleChange} value={formData.country}>
                                        {countries.map((element, index) => {
                                            return (
                                                <option onChange={handleChange} value={element}>{element}</option>
                                            );
                                        })}
                                    </select>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.country ? "" :
                                        response.error.error.country.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                                <div className="col-sm-6">
                                    <label className="form-label" htmlFor="city">Ваш город</label>
                                    <input class={response?.error && response?.error?.error?.city ? "form-control is-invalid" : "form-control"} id="city" name="city" type="text" placeholder="Санкт Петербург"  onChange={handleChange} value={formData.city}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.city ? "" :
                                        response.error.error.city.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                            </div>
                        :""}
                        {settings.auth.register.address ? 
                           <div className="row g-3 mb-7">
                                <div className="col-sm-6">
                                    <label className="form-label" htmlFor="address">Ваш адрес</label>
                                    <input class={response?.error && response?.error?.error?.address ? "form-control is-invalid" : "form-control"} id="address" name="address" type="text" placeholder="улица Пушкина дом колотушкина"  onChange={handleChange} value={formData.address}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.address ? "" :
                                        response.error.error.address.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                                <div className="col-sm-6">
                                        <label className="form-label" htmlFor="zip">Ваш почтовый индекс</label>
                                        <input class={response?.error && response?.error?.error?.zip ? "form-control is-invalid" : "form-control"} id="zip" name="zip" type="text" placeholder="228"  onChange={handleChange} value={formData.zip}/>
                                        {!response?.error ? "" : 
                                            !response?.error?.error?.zip ? "" :
                                            response.error.error.zip.map((element, index) => {
                                                return (
                                                    <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                                );
                                            })
                                        }
                                    </div>
                            </div>
                        :""}
                        
                        <div className="form-check mb-1">
                            <input class={response?.error && response?.error?.error?.terms ? "form-check-input is-invalid" : "form-check-input"} id="terms" name="terms" type="checkbox" onChange={handleChange} />
                            <label className="form-label fs--1 text-none" htmlFor="terms">
                                Я принимаю <a href="#">правила пользования </a>и <a href="#">политику конфиденциальности</a>
                            </label>
                            {!response?.error ? "" : 
                                !response?.error?.error?.terms ? "" :
                                response.error.error.terms.map((element, index) => {
                                    return (
                                        <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                    );
                                })
                            }
                        </div>
                        <div className="form-check mb-3">
                            <input class={response?.error && response?.error?.error?.promo ? "form-check-input is-invalid" : "form-check-input"} id="promo" name="promo" type="checkbox"  defaultChecked={true} onChange={handleChange}  />
                            <label className="form-label fs--1 text-none text-secondary" htmlFor="promo">
                                Я разрешаю присылать мне рекламные кампании
                            </label>
                            {!response?.error ? "" : 
                                !response?.error?.error?.promo ? "" :
                                response.error.error.promo.map((element, index) => {
                                    return (
                                        <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                    );
                                })
                            }
                        </div>
                        {settings.auth.register.captcha ? 
                            <div className="mb-1 text-center d-flex justify-content-center">
                                <ReCAPTCHA
                                    sitekey={settings.captcha_site_key}
                                    onChange={onChangeCaptcha}
                                />
                            </div>
                        :""}
                        {!response?.error ? "" : 
                            !response?.error?.error?.captcha ? "" :
                            response.error.error.captcha.map((element, index) => {
                                return (
                                    <div > CAPTCHA ERROR {element}</div>
                                );
                            })
                        }
                        <div className="text-center">
                            <button className="btn btn-primary w-50 mb-3" type="submit">Зарегистрироваться</button>
                        </div>
                        <div className="text-center">
                            <a className="fs--1 fw-bold" href="/login">
                                Войти в уже существующий аккаунт
                            </a>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
 };
 
 export default Register;