import convertTextsToString from "../../helpers/strings"

const BigImage = (data) => {
	let sliders = data.sliders;
	if (!sliders) {
		return <div>Loading </div>;
	}

	if(sliders.error){
		console.log(sliders);
		return <div>Error found check console </div>;
	}

    return (
		<div className="row g-3 mb-9">
			<div className="col-12">
				<div className="whooping-banner w-100 rounded-3 overflow-hidden">
					<div className="bg-holder z-index--1 banner-bg" style={{backgroundImage:  "url(" + sliders?.data[0]?.data?.image + ")"}}></div>
					<div className="banner-text light">
						<h2 className="text-warning-300 fw-bolder fs-lg-5 fs-xxl-6">{convertTextsToString(sliders?.data[0]?.data?.texts, "title")}</h2>
						<h3 className="fw-bolder fs-lg-3 fs-xxl-5 text-white light">{convertTextsToString(sliders?.data[0]?.data?.texts, "description")}</h3>
					</div>
					<a className="btn btn-lg btn-primary rounded-pill banner-button" href={sliders?.data[0].url}>{convertTextsToString(sliders?.data[0]?.data?.texts, "button_text")}</a>
				</div>
			</div>
		</div>
		
    );
};
 
 export default BigImage;