import { api_url, api_token } from '../../api/config'
import { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import FingerprintJS from  "@fingerprintjs/fingerprintjs";


function ModalPhoneChange(data) {
    const navigate = useNavigate();
    let hash = data.hash;
    const [formData, setFormData] = useState({});
    const fpPromise = FingerprintJS.load()
    const [response, setResponse] = useState({});
    const handleChange = (event) => {
        setFormData({
          ...formData,
          [event.target.name]: event.target.value
        });
    }

    let handleSubmit = (e) => {
        e.preventDefault();
        if(!localStorage.getItem("change_phone_token")){
            setResponse({error: {error: {code: ["Странная ошибка"]}}});
            return;
        }
        let visitorId = "";
        fpPromise
        .then(fp => fp.get())
        .then(result => {
            setResponse({})
            axios.post(api_url + 'api/v1/auth/change/user/phone', {
                fid: result.visitorId,
                hash: localStorage.getItem("change_phone_token"),
                code: formData.code,
            }, {
                headers: {
                    'C-Token': api_token,
                    'Authorization': `Bearer: ${localStorage.getItem("auth_token")}`
                }
            }).then(response => {
                setResponse(response.data);
                localStorage.removeItem("change_phone_token")
            }).catch(response => {
                var resp = {};
                resp.error = response.response.data
                setResponse(resp)
            });
        })
    };

    return (
        <div>
            <button class="d-none" type="button" id="openModalPhoneChangeBtn" data-bs-toggle="modal" data-bs-target="#phoneChangeModal" aria-haspopup="true" aria-expanded="false" data-bs-reference="parent"></button>
            <div class="modal fade" id="phoneChangeModal" data-bs-keyboard="false" tabindex="-1" aria-labelledby="phoneChangeModal" aria-hidden="true">
                <div class="modal-dialog modal-md modal-dialog-centered">
                    <div class="modal-content bg-100 p-6">
                    <div class="modal-header border-0 p-0 mb-2">
                        <h3 class="mb-0"></h3>
                        <button class="btn btn-sm btn-esplatform-secondary" data-bs-dismiss="modal" aria-label="Close"><span class="fas fa-times text-danger"></span></button>
                    </div>
                    <div class="modal-body px-0">
                        
                        
                    <div className="row flex-center pb-5">
                        <div className="col-sm-10 col-md-8 col-lg-5 col-xl-6 col-xxl-7">
                            <a className="d-flex flex-center text-decoration-none mb-7" href="/">
                                <div className="d-flex align-items-center fw-bolder fs-5 d-inline-block">
                                    <img src="/assets/img/icons/logo.png" alt="escasino" width="58" />
                                </div>
                            </a>
                            <div className="text-center mb-3">
                                <h3 className="text-1000">Смена Phone</h3>
                            </div>
                            <form onSubmit={handleSubmit} id="modalPhoneChangeForm">
                                <div className="mb-3 text-start">
                                    <label className="form-label" htmlFor="code">Код подтверждения с старой почты</label>
                                    <input class={response?.error && response?.error?.error?.code ? "form-control is-invalid" : "form-control"} id="code" name="code" type="code" placeholder="17235126" onChange={handleChange} value={formData.code}/>
                                    {!response?.error ? "" : 
                                        !response?.error?.error?.code ? "" :
                                        response.error.error.code.map((element, index) => {
                                            return (
                                                <div className="invalid-feedback mt-0 is-invalid">{element}</div>
                                            );
                                        })
                                    }
                                </div>
                                <div className="text-center">
                                    <button className="btn btn-primary mb-3 w-50" type="submit">Подтвердить действие</button>
                                </div>
                            </form>
                        </div>
                    </div>



                    </div>
                    </div>
                </div>
            </div>
        </div>
    );
 }
 
 export default ModalPhoneChange;
 